export class Mode {
    constructor() {
        this.isCleared = false;
        this.isGameOver = false;
    }
    getIsCleared() {
        return this.isCleared;
    }
    getIsGameOver() {
        return this.isGameOver;
    }
    reset() {
        this.isCleared = false;
        this.isGameOver = false;
    }
}
